// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { DaVinciLogo } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Foundations/DaVinciLogo)

figma.connect(DaVinciLogo, FIGMA_NODE_URL, {
  props: {
    variant: figma.enum('variant', { 'mark': 'mark', 'lockup': 'lockup' }),
  },
  example: ({ variant }) => (
    <DaVinciLogo variant={variant}></DaVinciLogo>
  ),
});
